 "<div><b>Púrpura</b></div><div style=\"font-family:ui-monospace,'SFMono-Regular',Menlo,Consolas,'Liberation Mono',monospace;font-size:.78em;opacity:.75\">wordart: 'purple'</div>": "<div><b>Paars</b></div><div style=\"font-family:ui-monospace,'SFMono-Regular',Menlo,Consolas,'Liberation Mono',monospace;font-size:.78em;opacity:.75\">wordart: 'purple'</div>",
